import{_ as r,C as s,o as a,c as i,a2 as e,E as n}from"./chunks/framework.BSaF8iZ6.js";const _=JSON.parse('{"title":"Bookings","description":"","frontmatter":{},"headers":[],"relativePath":"orders/booking-management.md","filePath":"orders/booking-management.md","lastUpdated":1789411447000}'),g={name:"orders/booking-management.md"};function l(d,o,h,p,c,m){const t=s("ImagePopup");return a(),i("div",null,[o[0]||(o[0]=e('<h1 id="bookings" tabindex="-1">Bookings <a class="header-anchor" href="#bookings" aria-label="Permalink to &quot;Bookings&quot;">​</a></h1><div class="page-roles"><span class="role role--seller">Seller</span></div><p>Sellers can sell bookable products, such as appointments, rentals, event tickets or table reservations. Each reservation a customer makes appears under <strong>Sales &gt;&gt; Bookings</strong>.</p><p>To create a bookable product, choose <strong>Bookable</strong> as the kind of product and fill in the <strong>Booking Type</strong> step. See <a href="./../catalog/product-management">Product Management</a>.</p><h2 id="the-calendar" tabindex="-1">The calendar <a class="header-anchor" href="#the-calendar" aria-label="Permalink to &quot;The calendar&quot;">​</a></h2><p>Go to <strong>Sales &gt;&gt; Bookings</strong>. The page opens on a calendar of the current week. Use the arrows to move between weeks.</p>',6)),n(t,{src:"/images/booking-management/bookings-calendar.png",alt:"The bookings calendar"}),o[1]||(o[1]=e('<p>Click a booking to see its <strong>Booking Details</strong>:</p><ul><li>the <strong>Booking Date</strong>, which is the day the order was placed, and the booked <strong>Time Slot</strong>;</li><li>the <strong>Order Id</strong>, and the <strong>Price</strong>, which is the grand total of the customer&#39;s whole order, including other sellers&#39; products and shipping;</li><li>the <strong>Status</strong> of the whole order, such as <strong>Done</strong>, <strong>Pending</strong>, <strong>Canceled</strong> or <strong>Closed</strong>;</li><li>the customer&#39;s name, email, phone number and billing address.</li></ul><p>Click <strong>View Details</strong> to open the order.</p><h2 id="the-list" tabindex="-1">The list <a class="header-anchor" href="#the-list" aria-label="Permalink to &quot;The list&quot;">​</a></h2><p>Click the list icon at the top right to see bookings as a table with the <strong>ID</strong>, <strong>Order ID</strong>, <strong>QTY</strong>, <strong>From</strong> and <strong>To</strong>. Use <strong>Filter</strong> to find bookings by date, and <strong>Export</strong> to download the list. Click the arrow icon on a row to open the order.</p>',5)),n(t,{src:"/images/booking-management/bookings-list.png",alt:"The bookings list"}),o[2]||(o[2]=e('<h2 id="bookings-and-orders" tabindex="-1">Bookings and orders <a class="header-anchor" href="#bookings-and-orders" aria-label="Permalink to &quot;Bookings and orders&quot;">​</a></h2><p>A booking is placed and paid for like any other order, so you handle it from <a href="./order-management">Order Management</a>:</p><ul><li>Bookings have nothing to ship. When all your products in the order are bookings or other products with nothing to ship, the order is <strong>Completed</strong> once you invoice it.</li><li>Request payment for it in the same way as other orders.</li></ul><p>Team members need <strong>Bookings</strong>, and <strong>Orders</strong> with <strong>View</strong> to open the order.</p>',4))])}const u=r(g,[["render",l]]);export{_ as __pageData,u as default};
